"use strict";(self.webpackChunkhudi=self.webpackChunkhudi||[]).push([[20884],{28453:(e,t,a)=>{a.d(t,{R:()=>s,x:()=>o});var i=a(96540);const r={},n=i.createContext(r);function s(e){const t=i.useContext(n);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),i.createElement(n.Provider,{value:t},e.children)}},48351:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>h,frontMatter:()=>s,metadata:()=>i,toc:()=>d});var i=a(73621),r=a(74848),n=a(28453);const s={title:"Migrating from Apache Iceberg to Apache Hudi",excerpt:"A practical guide to adopting Apache Hudi on existing Iceberg tables \u2014 via XTable metadata translation or a one-time rewrite \u2014 while keeping every Iceberg-based reader working through reverse sync.",description:"How to migrate Iceberg tables to Apache Hudi with XTable metadata conversion or a Spark rewrite, keeping Snowflake, BigQuery and Trino Iceberg readers working.",authors:["sivabalan"],category:"how-to",image:"/assets/images/blog/2025-07-02-Lakehouse-Architecture-apache-hudi-and-apache-iceberg.png",tags:["migration","apache xtable","apache iceberg","guide"]},o=void 0,l={authorsImageUrls:[void 0]},d=[{value:"Why Teams Move from Iceberg to Hudi",id:"why-teams-move-from-iceberg-to-hudi",level:2},{value:"Migrate the Writer, Keep the Readers",id:"migrate-the-writer-keep-the-readers",level:2},{value:"Option A: Convert Iceberg Metadata to Hudi with Apache XTable",id:"option-a-convert-iceberg-metadata-to-hudi-with-apache-xtable",level:2},{value:"Converted vs Native: Cutting the Writer Over",id:"converted-vs-native-cutting-the-writer-over",level:2},{value:"Option B: One-Time Rewrite with Spark",id:"option-b-one-time-rewrite-with-spark",level:2},{value:"What May Not Map One-to-One",id:"what-may-not-map-one-to-one",level:2},{value:"Validation Checklist and Rollback",id:"validation-checklist-and-rollback",level:2},{value:"Conclusion",id:"conclusion",level:2},{value:"FAQ",id:"faq",level:2}];function c(e){const t={a:"a",code:"code",em:"em",h2:"h2",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,n.R)(),...e.components},{PostFAQ:a}=t;return a||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("PostFAQ",!0),(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(t.p,{children:["You can adopt Apache Hudi on an existing Apache Iceberg table either by translating its metadata with ",(0,r.jsx)(t.a,{href:"https://xtable.apache.org",children:"Apache XTable"}),' \u2014 no data rewrite, since both formats store data as Parquet files \u2014 or via a one-time rewrite; and because XTable also works in the reverse direction, projecting a Hudi table back out as Iceberg, your existing Iceberg readers can keep working after the switch. That second point changes the shape of the whole exercise. "Migrating from Iceberg to Hudi" does not have to mean a hard cutover of every writer, reader, catalog entry and dashboard on the same weekend. It can mean moving just the ',(0,r.jsx)(t.em,{children:"write path"})," to Hudi \u2014 to get record-level indexes, streaming upserts and built-in table services \u2014 while every Snowflake, BigQuery or Trino consumer that speaks Iceberg continues reading the same table, unaware anything changed underneath."]}),"\n",(0,r.jsxs)(t.p,{children:["This guide walks through both migration options with working configuration and code, the cutover sequence that de-risks the switch, an honest look at which Iceberg features do not map one-to-one, and a validation checklist with a rollback story. It is the Iceberg-side companion to our guides on ",(0,r.jsx)(t.a,{href:"/blog/2026/07/28/using-hudi-with-apache-iceberg-via-xtable",children:"using Hudi with Apache Iceberg via XTable"})," and ",(0,r.jsx)(t.a,{href:"/blog/2026/08/04/migrating-from-delta-lake-to-hudi",children:"migrating from Delta Lake to Hudi"}),"."]}),"\n",(0,r.jsx)(t.h2,{id:"why-teams-move-from-iceberg-to-hudi",children:"Why Teams Move from Iceberg to Hudi"}),"\n",(0,r.jsx)(t.p,{children:"The migrations we see are almost always driven by the write side. Apache Iceberg has broad catalog and engine support, and for append-mostly batch analytics it serves many teams fine. The friction shows up when workloads become mutation-heavy or latency-sensitive:"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Record-level indexes for fast upserts."})," Hudi maintains a ",(0,r.jsx)(t.a,{href:"/docs/indexes",children:"multi-modal indexing subsystem"})," \u2014 record-level index, bloom filters, expression and secondary indexes \u2014 that maps record keys to file groups. An upsert locates exactly the files it must touch instead of planning a join or scan against the target to find matching rows. For CDC pipelines applying millions of scattered updates, this is routinely the difference between minutes and hours."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Merge-on-Read designed for streaming ingest."})," Hudi's MOR tables absorb updates as compact log files merged on read, so writers sustain high-frequency commits \u2014 minute-level or faster from Kafka, Flink or Spark Structured Streaming \u2014 without churning out rewritten Parquet on every batch."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Built-in table services."})," Compaction, clustering, cleaning and file sizing are part of the Hudi runtime and run inline or asynchronously without external orchestration. With Iceberg, that maintenance is left to engines, scheduled Spark procedures or a vendor service \u2014 someone has to own it."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"CDC-grade change streams."})," Hudi tables serve ",(0,r.jsx)(t.a,{href:"/docs/sql_queries#incremental-query",children:"incremental queries"}),": give me exactly the records that changed between two points on the timeline, including before/after images in CDC mode. Downstream pipelines chain off tables directly instead of re-reading snapshots and diffing."]}),"\n"]}),"\n",(0,r.jsxs)(t.p,{children:["The gap is measurable. In benchmarks run with the open-source ",(0,r.jsx)(t.a,{href:"https://github.com/onehouseinc/lake-loader",children:"LakeLoader"})," framework \u2014 Spark 3.5, Hudi 1.1.1, Iceberg 1.10.0, on S3 \u2014 we observed roughly 4\xd7 lower incremental write latency for Hudi on a 10 TB partitioned fact table with skewed updates, and about 8\xd7 lower steady-state latency on Merge-on-Read tables taking sparse, column-level updates, with Hudi's record-level index sidestepping the full-table-scan merge joins that dominate the alternative write path. The workload definitions are format-agnostic and repeatable, so you can rerun the comparison on your own update patterns before deciding."]}),"\n",(0,r.jsx)(t.p,{children:"The point is not that Iceberg cannot handle these workloads \u2014 it is that Hudi's write path, indexing and self-managing services are built for mutable, streaming-oriented workloads. If that describes the tables you are running, here is how to move them."}),"\n",(0,r.jsx)(t.h2,{id:"migrate-the-writer-keep-the-readers",children:"Migrate the Writer, Keep the Readers"}),"\n",(0,r.jsx)(t.p,{children:"The biggest source of migration risk is rarely the table itself \u2014 it is the long tail of consumers. A warehouse reading through an Iceberg catalog, BI dashboards, other teams' Spark jobs. A migration plan that requires all of them to change on cutover day is fragile enough that most teams never start."}),"\n",(0,r.jsx)(t.p,{children:"The two-way XTable pattern removes that requirement:"}),"\n",(0,r.jsxs)(t.ol,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Writers move to Hudi."})," Your ingestion pipeline gains Hudi's upsert indexes, MOR streaming writes and table services."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"XTable continuously projects the Hudi table back out as Iceberg."})," After each Hudi commit (or on a schedule), XTable translates the Hudi timeline into Iceberg metadata over the ",(0,r.jsx)(t.em,{children:"same"})," Parquet data files, and its catalog sync can keep Hive Metastore or AWS Glue entries current."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Readers keep reading Iceberg."})," Snowflake, BigQuery, Trino Iceberg catalogs, anything else that only speaks Iceberg \u2014 all keep working. They can each move to native Hudi reads later, on their own schedule, or never."]}),"\n"]}),"\n",(0,r.jsxs)(t.p,{children:["Because the data files are shared and only lightweight metadata is generated, the reverse projection is cheap and stays fresh. The migration decision decomposes: the writer cutover is one contained change, and every reader migration becomes optional and independent. We cover the reader-side mechanics in depth in the ",(0,r.jsx)(t.a,{href:"/blog/2026/07/28/using-hudi-with-apache-iceberg-via-xtable",children:"Hudi + Iceberg interoperability guide"}),"; the rest of this post focuses on getting the table and the writer onto Hudi."]}),"\n",(0,r.jsx)(t.h2,{id:"option-a-convert-iceberg-metadata-to-hudi-with-apache-xtable",children:"Option A: Convert Iceberg Metadata to Hudi with Apache XTable"}),"\n",(0,r.jsxs)(t.p,{children:["XTable (incubating) translates table metadata between Hudi, Iceberg and Delta Lake in any direction. Pointed at an Iceberg table, it reads the Iceberg snapshot and writes Hudi metadata \u2014 a ",(0,r.jsx)(t.code,{children:".hoodie"})," timeline with schema, commit history, partition and column statistics \u2014 referencing the existing Parquet files in place. Nothing is copied or rewritten."]}),"\n",(0,r.jsxs)(t.p,{children:["Grab the XTable bundled jar (build from ",(0,r.jsx)(t.a,{href:"https://github.com/apache/incubator-xtable",children:"source"})," or download from GitHub packages) and create a config:"]}),"\n",(0,r.jsx)(t.pre,{children:(0,r.jsx)(t.code,{className:"language-yaml",metastring:'md title="iceberg_to_hudi.yaml"',children:"sourceFormat: ICEBERG\ntargetFormats:\n  - HUDI\ndatasets:\n  -\n    tableBasePath: s3://warehouse/orders\n    tableDataPath: s3://warehouse/orders/data\n    tableName: orders\n    partitionSpec: order_date:VALUE\n"})}),"\n",(0,r.jsxs)(t.p,{children:[(0,r.jsx)(t.code,{children:"tableDataPath"})," is needed for Iceberg sources when data files live under a subdirectory (the layout Iceberg warehouses typically use) rather than directly under the base path. Then run the sync:"]}),"\n",(0,r.jsx)(t.pre,{children:(0,r.jsx)(t.code,{className:"language-shell",children:"java -jar path/to/xtable-utilities-bundled.jar --datasetConfig iceberg_to_hudi.yaml\n"})}),"\n",(0,r.jsx)(t.p,{children:"The run produces Hudi metadata under the table's base path. Any Hudi-capable engine can now read the table \u2014 the same files your Iceberg readers are still using. XTable syncs incrementally by default (translating only new commits, falling back to a full sync when needed), so re-running it on a schedule keeps the Hudi view current for as long as the Iceberg writer remains active. Registering the table in your catalog of choice makes it visible to Hudi readers alongside the existing Iceberg entry."}),"\n",(0,r.jsx)(t.p,{children:"At this stage you have a zero-copy, read-ready Hudi table and have changed nothing about production. That alone is useful \u2014 you can benchmark Hudi readers against real data before committing to anything."}),"\n",(0,r.jsx)(t.h2,{id:"converted-vs-native-cutting-the-writer-over",children:"Converted vs Native: Cutting the Writer Over"}),"\n",(0,r.jsxs)(t.p,{children:["Metadata translation gets you Hudi ",(0,r.jsx)(t.em,{children:"reads"}),". The features that motivate the migration \u2014 record-level index lookups, streaming upserts, change streams, self-managing table services \u2014 come from Hudi ",(0,r.jsx)(t.em,{children:"writing"})," the table: assigning record keys, maintaining indexes and the metadata table, running services against its own timeline. To get them, you cut the writer over. The sequence:"]}),"\n",(0,r.jsxs)(t.ol,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Stop the Iceberg writer."})," Pause ingestion at a clean commit boundary."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Run a final XTable sync"})," (Iceberg \u2192 Hudi) so the Hudi metadata reflects the last Iceberg commit exactly."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Start the Hudi writer"})," against the table's base path, configuring the record key, ordering fields (",(0,r.jsx)(t.code,{children:"hoodie.table.ordering.fields"}),") and partitioning to match your workload. From here, commits land natively on the Hudi timeline, indexes are built and maintained, and table services take over maintenance."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Enable reverse sync"})," (Hudi \u2192 Iceberg) \u2014 via the XTable job on a schedule with ",(0,r.jsx)(t.code,{children:"sourceFormat: HUDI"}),", or per-commit through the Hudi Streamer sync extension (",(0,r.jsx)(t.a,{href:"/docs/syncing_xtable",children:"docs"}),") \u2014 so Iceberg readers see every new Hudi commit."]}),"\n"]}),"\n",(0,r.jsxs)(t.p,{children:["The gap between steps 1 and 4 is minutes of paused ingestion, not a data-copy window \u2014 for most tables the downtime is a single deferred micro-batch. Validate the native-write onboarding on a staging copy first: depending on the table's layout and key structure, some tables are better served by Hudi's ",(0,r.jsx)(t.a,{href:"/docs/migration_guide",children:"bootstrap mechanism"})," or a full rewrite (Option B below) to get a fully native file layout with populated Hudi metadata fields, rather than writing directly on top of converted metadata. Either way, the end state is the same: Hudi owns the write path, Iceberg remains a continuously refreshed read projection."]}),"\n",(0,r.jsx)(t.h2,{id:"option-b-one-time-rewrite-with-spark",children:"Option B: One-Time Rewrite with Spark"}),"\n",(0,r.jsx)(t.p,{children:"If the table is modest in size, or you want to change its physical layout anyway \u2014 new partitioning, clustering by query predicates, cleaning out accumulated small files \u2014 a full rewrite is the simpler and sometimes better move. Read the Iceberg table with Spark, write a Hudi table:"}),"\n",(0,r.jsx)(t.pre,{children:(0,r.jsx)(t.code,{className:"language-scala",children:'// spark-shell with both Iceberg and Hudi bundles on the classpath\nval df = spark.read.format("iceberg").load("s3://warehouse/orders")\n\ndf.write.format("hudi").\n  option("hoodie.table.name", "orders").\n  option("hoodie.datasource.write.recordkey.field", "order_id").\n  option("hoodie.datasource.write.partitionpath.field", "order_date").\n  option("hoodie.table.ordering.fields", "updated_at").\n  option("hoodie.datasource.write.operation", "bulk_insert").\n  mode("overwrite").\n  save("s3://warehouse/orders_hudi")\n'})}),"\n",(0,r.jsxs)(t.p,{children:["This is a plain batch job \u2014 parallelize by partition for very large tables, as shown in the ",(0,r.jsx)(t.a,{href:"/docs/migration_guide",children:"migration guide"}),", which also covers Hudi Streamer's bootstrap mode (including METADATA_ONLY, which builds skeleton files instead of rewriting data). The rewrite costs a full pass over the data but produces a completely native Hudi table with no conversion caveats, and cutover is just repointing the writer and backfilling the delta that accrued during the copy. See the ",(0,r.jsx)(t.a,{href:"/docs/quick-start-guide",children:"Spark quick start"})," for current write configurations. And note the reverse-sync pattern applies here identically: run XTable over the new Hudi table and your Iceberg readers follow along to the new location."]}),"\n",(0,r.jsx)(t.h2,{id:"what-may-not-map-one-to-one",children:"What May Not Map One-to-One"}),"\n",(0,r.jsx)(t.p,{children:"An honest migration plan checks feature parity per table rather than assuming it. Watch for:"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Merge-on-read delete files."})," XTable syncs the underlying Parquet data files; Iceberg v2 position/equality delete files are not carried through the conversion. Compact them away first (e.g. Iceberg's ",(0,r.jsx)(t.code,{children:"rewrite_data_files"})," / ",(0,r.jsx)(t.code,{children:"rewrite_position_delete_files"})," procedures) so the source snapshot is materialized in data files before converting. The same applies to newer v3 constructs such as deletion vectors."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Hidden partitioning and partition evolution."})," Iceberg partitions by column transforms (",(0,r.jsx)(t.code,{children:"days(ts)"}),", ",(0,r.jsx)(t.code,{children:"bucket(n, id)"}),") invisible to queries, and lets the partition spec evolve over time. Hudi partitions by explicit partition path fields. Simple value and date-based partitioning translate cleanly; bucket transforms and tables carrying multiple historical partition specs need per-table validation, and a rewrite (Option B) into a layout of your choosing is often the cleaner answer for them."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Iceberg-specific column types and metadata."})," Features tied to recent Iceberg spec versions \u2014 row lineage, variant type in v3, engine-specific catalog behaviors \u2014 have no direct Hudi equivalent or map differently. Inventory what each table actually uses; most analytics tables use none of these."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Snapshot history."})," The converted Hudi table's timeline starts at conversion. Old Iceberg snapshots remain time-travelable through the Iceberg metadata (which stays intact on storage), but do not appear as Hudi commits."]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"None of these block a migration; they determine which tables take the metadata-translation fast path and which deserve a rewrite."}),"\n",(0,r.jsx)(t.h2,{id:"validation-checklist-and-rollback",children:"Validation Checklist and Rollback"}),"\n",(0,r.jsx)(t.p,{children:"Before decommissioning anything, verify per table:"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Row counts and checksums"})," match between the Iceberg source and Hudi target (and, after cutover, between the Hudi table and its reverse-synced Iceberg projection)."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Schema fidelity"})," \u2014 column types, nullability and nested structures survived translation."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Partition pruning"})," works: run a partition-filtered query against the Hudi table and confirm file skipping."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Reader smoke tests"})," from every consumer that matters: native Hudi reads from Spark/Trino, and Iceberg reads from the warehouse or catalog your downstream teams use."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"Writer dry run"})," on staging: upsert, delete, then read back and confirm index behavior and table service activity on the timeline."]}),"\n"]}),"\n",(0,r.jsx)(t.p,{children:"The rollback story is what makes this migration low-stakes. Until you delete it, the original Iceberg metadata is untouched \u2014 XTable conversion writes new metadata alongside, and Option B writes to a new path entirely \u2014 so reverting before cutover means simply not proceeding. After cutover, reverse sync means there is a live, continuously updated Iceberg view of the table at all times: if a downstream Iceberg consumer misbehaves, it keeps reading Iceberg while you debug, and in the worst case you can resume Iceberg-native writes from the current state rather than restoring backups. Keep the old metadata around until the new write path has run through a full cycle of your table services and audits."}),"\n",(0,r.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,r.jsxs)(t.p,{children:["Table format choice used to be a one-way architectural door; XTable makes it a revolving one. Adopting Hudi on an Iceberg estate is not a monolithic rewrite: translate metadata in place to light up Hudi reads, cut writers over table-by-table to gain ",(0,r.jsx)(t.a,{href:"/docs/indexes",children:"indexes"}),", streaming upserts and built-in table services, and let reverse sync keep every Iceberg-based consumer running exactly as before. Rewrite the tables that want a new layout; translate the rest. Start with one mutation-heavy table where Hudi's write path pays off most, prove the loop end to end \u2014 convert, cut over, reverse-sync, validate \u2014 and expand from there, knowing the decision stays reversible the whole way."]}),"\n",(0,r.jsx)(t.h2,{id:"faq",children:"FAQ"}),"\n",(0,r.jsx)(a,{heading:null,items:[{question:"Can Snowflake still read my table after migrating to Hudi?",answer:"Yes. Apache XTable can continuously project a Hudi table back out as Iceberg metadata over the same Parquet data files, and can sync catalogs like AWS Glue or Hive Metastore. Snowflake, BigQuery and other engines that read Iceberg keep working against that projection, so reader migrations become optional and can happen on their own schedule."},{question:"Does migrating from Iceberg to Hudi require rewriting data?",answer:"Not necessarily. Both formats store data as Parquet files, so Apache XTable can translate the Iceberg metadata into a Hudi timeline referencing the existing files in place, with no data copy. A full rewrite via Spark is only needed when you want to change the physical layout, such as new partitioning or clustering, or for tables whose Iceberg features don't translate cleanly."},{question:"What do I gain by moving the write path to Hudi?",answer:"Hudi's writer maintains record-level and bloom indexes that make scattered upserts fast, supports Merge-on-Read tables built for high-frequency streaming ingestion, runs compaction, clustering and cleaning as built-in table services, and serves incremental and CDC queries off its timeline. These come from Hudi writing the table, which is why the cutover targets writers first."},{question:"Can I go back to Iceberg if the migration doesn't work out?",answer:"Yes. The original Iceberg metadata stays intact on storage until you delete it, so before cutover, rollback means simply not proceeding. After cutover, reverse sync maintains a live Iceberg view of the table at all times, so in the worst case you can resume Iceberg-native writes from the current state rather than restoring from backups."},{question:"How much downtime does the writer cutover take?",answer:"Minutes, not hours. The sequence is: pause the Iceberg writer at a commit boundary, run a final XTable sync so the Hudi metadata matches exactly, start the Hudi writer, and enable reverse sync from Hudi back to Iceberg. There is no data copy in that window, so the downtime is typically a single deferred micro-batch."},{question:"Do Iceberg v2 delete files survive the conversion?",answer:"No. XTable syncs the underlying Parquet data files, and Iceberg position or equality delete files are not carried through. Run Iceberg's compaction procedures to materialize deletes into data files before converting, so the snapshot XTable translates is fully represented in Parquet."}]})]})}function h(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},73621:e=>{e.exports=JSON.parse('{"permalink":"/blog/2026/08/05/migrating-from-apache-iceberg-to-hudi","editUrl":"https://github.com/apache/hudi/edit/asf-site/website/blog/blog/2026-08-05-migrating-from-apache-iceberg-to-hudi.md","source":"@site/blog/2026-08-05-migrating-from-apache-iceberg-to-hudi.md","title":"Migrating from Apache Iceberg to Apache Hudi","description":"How to migrate Iceberg tables to Apache Hudi with XTable metadata conversion or a Spark rewrite, keeping Snowflake, BigQuery and Trino Iceberg readers working.","date":"2026-08-05T00:00:00.000Z","tags":[{"inline":true,"label":"migration","permalink":"/blog/tags/migration"},{"inline":true,"label":"apache xtable","permalink":"/blog/tags/apache-xtable"},{"inline":true,"label":"apache iceberg","permalink":"/blog/tags/apache-iceberg"},{"inline":true,"label":"guide","permalink":"/blog/tags/guide"}],"readingTime":13.07,"hasTruncateMarker":false,"authors":[{"name":"Sivabalan Narayanan","url":"https://www.linkedin.com/in/sivabalan-narayanan-1040b45/","imageURL":"/assets/images/authors/sivabalan.jpg","key":"sivabalan","page":null}],"frontMatter":{"title":"Migrating from Apache Iceberg to Apache Hudi","excerpt":"A practical guide to adopting Apache Hudi on existing Iceberg tables \u2014 via XTable metadata translation or a one-time rewrite \u2014 while keeping every Iceberg-based reader working through reverse sync.","description":"How to migrate Iceberg tables to Apache Hudi with XTable metadata conversion or a Spark rewrite, keeping Snowflake, BigQuery and Trino Iceberg readers working.","authors":["sivabalan"],"category":"how-to","image":"/assets/images/blog/2025-07-02-Lakehouse-Architecture-apache-hudi-and-apache-iceberg.png","tags":["migration","apache xtable","apache iceberg","guide"]},"unlisted":false,"lastUpdatedAt":1786026027000,"prevItem":{"title":"Apache Hudi vs Apache Iceberg for CDC Workloads","permalink":"/blog/2026/08/06/hudi-vs-iceberg-for-cdc-workloads"},"nextItem":{"title":"Migrating from Delta Lake to Apache Hudi","permalink":"/blog/2026/08/04/migrating-from-delta-lake-to-hudi"}}')}}]);